    'docs_exp_rec3' => 'કેટેગરી પસંદ કરો, રકમ, તારીખ અને વિક્રેતા દાખલ કરો',
    'docs_exp_rec4' => 'રેકોર્ડ-કીપિંગ માટે રસીદની છબી અપલોડ કરો',
    'docs_exp_recording' => 'ખર્ચ નોંધવો',
    'docs_exp_reports' => 'નાણાકીય અહેવાલો',
    'docs_exp_void' => 'ખર્ચ રદ કરવો',
    'docs_exp_void_desc' => 'ખોટા ખર્ચને ઓડિટ ટ્રેલમાં રાખતાં રદ કરો',
    'docs_faq_a1' => 'લોગ ઇન કર્યા પછી, તમારી પ્રથમ પ્રોપર્ટી ઉમેરો, તેમાં યુનિટ્સ બનાવો, ભાડૂઆતોની નોંધણી કરો, લીઝ બનાવો અને ચૂકવણીઓ નોંધવાનું શરૂ કરો. પગલા-દર-પગલા સૂચનાઓ માટે Getting Started માર્ગદર્શિકા અનુસરો.',
    'docs_faq_a10' => 'અમારી સપોર્ટ ટીમનો WhatsApp અથવા ઇમેઇલ દ્વારા સંપર્ક કરો. Enterprise ટાયર સબ્સ્ક્રાઇબર્સને ઝડપી પ્રતિભાવ સમય સાથે અગ્રતા સપોર્ટ મળે છે.',
    'docs_faq_a2' => 'હા! FIS Real Estate એ પ્રોગ્રેસિવ વેબ એપ (PWA) છે. તેને તમારા ઉપકરણ પર ઇન્સ્ટોલ કરો અને ઓફલાઇન કામ કરવાનું ચાલુ રાખો. જ્યારે તમે ઇન્ટરનેટ સાથે ફરીથી કનેક્ટ થાઓ ત્યારે તમારા ફેરફારો આપોઆપ સિંક થશે.',
    'docs_faq_a3' => 'તમને તમે સંચાલિત કરો છો તે યુનિટ્સની સંખ્યાને તમારા ટાયર દર સાથે ગુણાકાર કરીને માસિક બિલ કરવામાં આવે છે. Basic %1$s TZS/યુનિટ/મહિનો છે, Professional %2$s છે, અને Enterprise %3$s છે. ડિસ્કાઉન્ટ લાગુ થઈ શકે છે.',
    'docs_faq_a4' => 'ટાયર અપગ્રેડની વિનંતી કરવા માટે FIS Real Estate સપોર્ટ ટીમનો WhatsApp અથવા ઇમેઇલ દ્વારા સંપર્ક કરો. તમારું સબ્સ્ક્રિપ્શન અપડેટ થશે અને તમને તરત જ નવી સુવિધાઓની ઍક્સેસ મળશે.',
    'docs_faq_a5' => 'હા, Professional ટાયર અથવા તેથી ઉપરના સાથે. Tenant Portal ભાડૂઆતોને લોગ ઇન કરવા, તેમનું બેલેન્સ, ચૂકવણી ઇતિહાસ અને લીઝ વિગતો જોવાની મંજૂરી આપે છે. તમે ભાડૂઆત દીઠ પોર્ટલ ઍક્સેસ સક્ષમ/અક્ષમ કરી શકો છો.',
    'docs_faq_a6' => 'મોડી ફી તમારા રૂપરેખાંકન આધારે આપોઆપ ગણવામાં આવે છે. તમે ફી પ્રકાર (ટકાવારી અથવા નિશ્ચિત), ગ્રેસ પિરિયડ અને મહત્તમ મર્યાદા સેટ કરો છો. જ્યારે ભાડું નિયત તારીખ વત્તા ગ્રેસ પિરિયડ સુધીમાં ચૂકવવામાં ન આવે ત્યારે ફી લાગુ થાય છે.',
    'docs_faq_a7' => 'હા, તમે કોઈ વધારાના ખર્ચ વિના અમર્યાદિત પ્રોપર્ટીઓનું સંચાલન કરી શકો છો. દરેક પ્રોપર્ટીની પોતાની સેટિંગ્સ, યુનિટ્સ અને ભાડૂઆતો હોઈ શકે છે. ડેશબોર્ડ તમારી બધી પ્રોપર્ટીઓમાં ડેટા એકત્રિત કરે છે.',
    'docs_faq_a8' => 'સિસ્ટમ અંગ્રેજી, સ્વાહિલી (Kiswahili) અને અરબી (જમણેથી-ડાબે લેઆઉટ સાથે) ને સમર્થન આપે છે. ટોચની બારમાં ગ્લોબ આઇકનનો ઉપયોગ કરીને કોઈપણ સમયે ભાષા બદલો.',
    'docs_faq_a9' => 'મોટાભાગના યાદી દૃશ્યો અને અહેવાલોમાં Export/CSV બટન હોય છે. Excel અથવા Google Sheets માં ખૂલતી CSV ફાઇલ તરીકે ડેટા ડાઉનલોડ કરવા તેને ક્લિક કરો. એડમિન્સ Backup પૃષ્ઠ પરથી સંપૂર્ણ ડેટાબેઝ બેકઅપ પણ બનાવી શકે છે.',
