    'docs_gs_create_leases_desc' => 'ભાડૂઆતોને લીઝ કરાર સાથે યુનિટ્સ સાથે લિંક કરો. ભાડું, તારીખો અને ચૂકવણી આવર્તન સેટ કરો.',
