    'docs_gs_first_login_desc' => 'તમારું એકાઉન્ટ પ્રોવિઝન થયા પછી, તમને ઇમેઇલ અથવા WhatsApp દ્વારા લોગિન ઓળખપત્રો પ્રાપ્ત થશે. તમારા ટેનન્ટ URL પર સાઇન ઇન કરવા તેનો ઉપયોગ કરો.',
    'docs_gs_help' => 'મદદ જોઈએ છે? WhatsApp અથવા ઇમેઇલ દ્વારા સપોર્ટનો સંપર્ક કરો. સામાન્ય પ્રશ્નો માટે FAQ વિભાગ તપાસો.',
    'docs_gs_intro' => 'FIS Real Estate માં આપનું સ્વાગત છે — તાંઝાનિયા અને તેની બહાર મકાનમાલિકો અને પ્રોપર્ટી મેનેજર્સ માટે રચાયેલ એક વ્યાપક પ્રોપર્ટી મેનેજમેન્ટ સિસ્ટમ.',
    'docs_gs_languages' => 'ભાષા સમર્થન',
    'docs_gs_languages_desc' => 'સિસ્ટમ અંગ્રેજી, સ્વાહિલી (Kiswahili) અને અરબી (જમણેથી-ડાબે લેઆઉટ સાથે) ને સમર્થન આપે છે. ટોચની બારમાં ગ્લોબ આઇકનનો ઉપયોગ કરીને ભાષા બદલો.',
    'docs_gs_offline' => 'ઓફલાઇન અને PWA સમર્થન',
    'docs_gs_offline_desc' => 'FIS Real Estate પ્રોગ્રેસિવ વેબ એપ (PWA) તરીકે ઓફલાઇન કામ કરે છે. તમે તેને તમારા ઉપકરણ પર ઇન્સ્ટોલ કરી શકો છો અને ઇન્ટરનેટ વિના પણ કામ કરવાનું ચાલુ રાખી શકો છો. જ્યારે તમે ફરીથી કનેક્ટ થાઓ ત્યારે ફેરફારો આપોઆપ સિંક થાય છે.',
    'docs_gs_pro_desc' => 'ટેનન્ટ પોર્ટલ, રિમાઇન્ડર્સ, દસ્તાવેજ સંચાલન',
