    'docs_gw_intro' => 'ડિજિટલ રીતે ચૂકવણી સ્વીકારવા મોબાઇલ મની પેમેન્ટ ગેટવેને એકીકૃત કરો. Selcom, M-Pesa, Airtel Money અને Tigo Pesa ને સમર્થન આપે છે.',
    'docs_gw_log' => 'ટ્રાન્ઝેક્શન લોગ',
    'docs_gw_log_desc' => 'બધા ગેટવે ટ્રાન્ઝેક્શન્સને તેમની સ્થિતિ સાથે જુઓ (initiated, pending, completed, failed). તારીખ, ગેટવે અથવા સ્થિતિ પ્રમાણે ફિલ્ટર કરો. નિષ્ફળ ટ્રાન્ઝેક્શન્સમાં મુશ્કેલીનિવારણ માટે ભૂલની વિગતો સામેલ છે.',
    'docs_gw_mpesa' => 'Vodacom M-Pesa મોબાઇલ મની',
    'docs_gw_reconciliation' => 'ઓટો-રિકન્સિલિએશન',
    'docs_gw_reconciliation_desc' => 'સિસ્ટમ આપોઆપ ગેટવે ટ્રાન્ઝેક્શન્સને ભાડૂઆતની ચૂકવણીઓ સાથે મેળ કરે છે. કોઈપણ મેળ ન ખાતા ટ્રાન્ઝેક્શન્સ એડમિન સમીક્ષા માટે મેન્યુઅલ રિકન્સિલિએશન કતારમાં દેખાય છે.',
