    'docs_insp_comparison' => 'મૂવ-ઇન વિરુદ્ધ મૂવ-આઉટ સરખામણી',
    'docs_insp_comparison_desc' => 'મૂવ-આઉટ નિરીક્ષણ બનાવતી વખતે, સિસ્ટમ મૂવ-ઇન નિરીક્ષણમાંથી વસ્તુઓ પૂર્વ-ભરે છે. અહેવાલ કોઈપણ બગાડને પ્રકાશિત કરતી બાજુ-બાજુ સરખામણી બતાવે છે. આ સીધું જ ડિપોઝિટ કપાત સાથે લિંક કરે છે.',
    'docs_insp_conducting' => 'નિરીક્ષણ કરવું',
    'docs_insp_cstep1' => '<strong>Inspections</strong> પર જાઓ અને <strong>New Inspection</strong> પર ક્લિક કરો',
    'docs_insp_cstep2' => 'યુનિટ, ભાડૂઆત અને નિરીક્ષણ પ્રકાર પસંદ કરો',
    'docs_insp_cstep3' => 'ટેમ્પ્લેટ પસંદ કરો અથવા ડિફોલ્ટનો ઉપયોગ કરો',
    'docs_insp_cstep4' => 'દરેક વસ્તુને રેટ કરો: Excellent, Good, Fair, Poor, Damaged અથવા Missing',
    'docs_insp_cstep5' => 'પુરાવા તરીકે દરેક વસ્તુ માટે ફોટા અપલોડ કરો',
    'docs_insp_cstep6' => 'નોંધો ઉમેરો અને નિરીક્ષણને completed તરીકે ચિહ્નિત કરો',
    'docs_insp_intro' => 'Inspections મોડ્યુલ મૂવ-ઇન, મૂવ-આઉટ અને નિયમિત પ્રોપર્ટી નિરીક્ષણોને સંભાળે છે. રૂમ-દર-રૂમ ચેકલિસ્ટ અને ફોટા સાથે દરેક યુનિટની સ્થિતિનું દસ્તાવેજીકરણ કરો.',
    'docs_insp_movein' => 'મૂવ-ઇન',
    'docs_insp_movein_desc' => 'જ્યારે ભાડૂઆત અંદર આવે ત્યારે કરવામાં આવે છે. યુનિટની પ્રારંભિક સ્થિતિનું દસ્તાવેજીકરણ કરે છે.',
    'docs_insp_moveout' => 'મૂવ-આઉટ',
    'docs_insp_moveout_desc' => 'જ્યારે ભાડૂઆત નીકળે ત્યારે કરવામાં આવે છે. નુકસાન ઓળખવા મૂવ-ઇન નિરીક્ષણ સામે સરખાવવામાં આવે છે.',
    'docs_insp_report' => 'નિરીક્ષણ અહેવાલો',
    'docs_insp_report_desc' => 'સ્થિતિ રેટિંગ્સ, ફોટા અને સરખામણી ડેટા સાથે પ્રિન્ટ કરી શકાય તેવા PDF અહેવાલો બનાવો. અહેવાલોમાં નિરીક્ષક સહી ફીલ્ડ્સ અને સ્થિતિ લેજેન્ડ્સ સામેલ છે.',
    'docs_insp_routine' => 'નિયમિત',
    'docs_insp_routine_desc' => 'ભાડૂઆતકાળ દરમિયાન સામયિક નિરીક્ષણો.',
    'docs_insp_templates' => 'નિરીક્ષણ ટેમ્પ્લેટ્સ',
    'docs_insp_templates_desc' => 'કયા રૂમ અને વસ્તુઓનું નિરીક્ષણ કરવું તે વ્યાખ્યાયિત કરતા પુનઃઉપયોગ કરી શકાય તેવા ટેમ્પ્લેટ્સ બનાવો. દરેક ટેમ્પ્લેટમાં રૂમની યાદી હોય છે, અને દરેક રૂમમાં તપાસવાની વસ્તુઓ હોય છે (દિવાલો, ફ્લોર, છત, દરવાજા, બારીઓ, ફિક્સ્ચર્સ, ઉપકરણો).',
    'docs_insp_types' => 'નિરીક્ષણ પ્રકારો',
    'docs_lease_active' => 'હાલમાં અમલમાં',
    'docs_lease_create' => 'લીઝ બનાવવો',
    'docs_lease_expired' => 'સમાપ્તિ તારીખ પસાર થઈ ગઈ છે',
    'docs_lease_intro' => 'લીઝ ભાડૂઆતોને ઔપચારિક ભાડા કરાર સાથે યુનિટ્સ સાથે લિંક કરે છે. તેઓ ભાડાની રકમ, તારીખો, ચૂકવણી આવર્તન અને શરતોને ટ્રેક કરે છે.',
    'docs_lease_pdf' => 'PDF જનરેશન',
    'docs_lease_pdf_desc' => 'ટેમ્પ્લેટ્સમાંથી વ્યાવસાયિક લીઝ કરાર PDF બનાવો. તમે PDF ને સીધું ભાડૂઆતને ડાઉનલોડ, પ્રિન્ટ અથવા ઇમેઇલ કરી શકો છો.',
    'docs_lease_renewal' => 'લીઝ નવીકરણ',
    'docs_lease_renewal_desc' => 'જ્યારે લીઝ સમાપ્ત થવાના હોય ત્યારે સિસ્ટમ તમને ચેતવણી આપે છે (renewal_alert_days સેટિંગ આધારે). તમે સમાન શરતો સાથે નવીકરણ કરી શકો છો અથવા ભાડાની રકમ અને શરતો અપડેટ કરી શકો છો. નવીકૃત લીઝ મૂળ સાથે લિંક કરતી શ્રૃંખલા જાળવે છે.',
    'docs_lease_renewed' => 'નવા લીઝ દ્વારા બદલાયેલ',
