    'docs_lease_step4' => 'ચૂકવણી આવર્તન પસંદ કરો: માસિક, ત્રિમાસિક અથવા વાર્ષિક',
    'docs_lease_step5' => 'ચૂકવણી નિયત દિવસ (1–28) અને નવીકરણ ચેતવણી દિવસો સેટ કરો',
    'docs_lease_step6' => 'કોઈપણ વધારાની શરતો ઉમેરો',
    'docs_lease_step7' => 'સાચવો — યુનિટ સ્થિતિ આપોઆપ Occupied માં બદલાઈ જશે',
    'docs_lease_templates' => 'લીઝ ટેમ્પ્લેટ્સ',
    'docs_lease_templates_desc' => '<code>{{tenant_name}}</code>, <code>{{rent_amount}}</code>, <code>{{start_date}}</code> જેવા પ્લેસહોલ્ડર્સ સાથે પુનઃઉપયોગ કરી શકાય તેવા લીઝ ટેમ્પ્લેટ્સ બનાવો. લીઝ PDF બનાવતી વખતે, પ્લેસહોલ્ડર્સ આપોઆપ ભરાઈ જાય છે.',
    'docs_lease_terminated' => 'વહેલા સમાપ્ત થયેલ',
    'docs_lease_termination' => 'લીઝ સમાપ્તિ',
    'docs_lease_termination_desc' => 'કારણ અને તારીખ સાથે લીઝને વહેલા સમાપ્ત કરો. સિસ્ટમ નોટિસ પિરિયડને ટ્રેક કરે છે અને ડિપોઝિટ સેટલમેન્ટ વર્કફ્લો સાથે લિંક કરે છે.',
    'docs_mnt_contractors' => 'કોન્ટ્રાક્ટર સંચાલન',
    'docs_mnt_contractors_desc' => 'કોન્ટ્રાક્ટર્સની તેમની વિશેષતાઓ, કલાકદીઠ દર અને સંપર્ક માહિતી સાથે યાદી જાળવો. ચોક્કસ જાળવણી વિનંતીઓ માટે કોન્ટ્રાક્ટર્સ સોંપો અને તેમના કામને ટ્રેક કરો.',
    'docs_mnt_costs' => 'ખર્ચ ટ્રેકિંગ',
    'docs_mnt_costs_desc' => 'દરેક જાળવણી કામ માટે અંદાજિત અને વાસ્તવિક ખર્ચ નોંધો. જાળવણી અહેવાલો દ્વારા પ્રોપર્ટી દીઠ, કેટેગરી દીઠ અને કોન્ટ્રાક્ટર દીઠ ખર્ચને ટ્રેક કરો.',
    'docs_mnt_intro' => 'Maintenance મોડ્યુલ વર્ક ઓર્ડર્સ, કોન્ટ્રાક્ટર સોંપણીઓ અને સમારકામ ખર્ચ ટ્રેકિંગનું સંચાલન કરે છે. સમસ્યાઓ નોંધો, કોન્ટ્રાક્ટર્સ સોંપો અને પૂર્ણ થાય ત્યાં સુધી કામ ટ્રેક કરો.',
    'docs_mnt_r1' => '<strong>Maintenance</strong> પર જાઓ અને <strong>New Request</strong> પર ક્લિક કરો',
    'docs_mnt_r2' => 'યુનિટ અને કેટેગરી પસંદ કરો (Plumbing, Electrical, Structural, વગેરે)',
    'docs_mnt_r3' => 'અગ્રતા સેટ કરો: Low, Medium, High અથવા Urgent',
    'docs_mnt_r4' => 'વર્ણન ઉમેરો અને સમસ્યાના ફોટા અપલોડ કરો',
    'docs_mnt_reports' => 'જાળવણી અહેવાલો',
    'docs_mnt_reports_desc' => 'જાળવણી ડેટા CSV તરીકે નિકાસ કરો. પ્રોપર્ટી દીઠ, કેટેગરી દીઠ ખર્ચ, કોન્ટ્રાક્ટર કામગીરી અને પ્રતિભાવ સમય પરના અહેવાલો જુઓ.',
    'docs_mnt_requests' => 'જાળવણી વિનંતીઓ',
    'docs_mnt_workflow' => 'સ્થિતિ વર્કફ્લો',
    'docs_mnt_workflow_desc' => 'વિનંતીઓ આ સ્થિતિઓમાંથી પસાર થાય છે:',
    'docs_pay_bank' => 'સીધી બેંક ડિપોઝિટ અથવા વાયર ટ્રાન્સફર',
    'docs_pay_bulk' => 'બલ્ક ચૂકવણી નોંધણી',
    'docs_pay_bulk_desc' => 'એકસાથે અનેક ભાડૂઆતો માટે ચૂકવણીઓ નોંધો. જ્યારે તમને એક જ દિવસે અનેક ચૂકવણીઓ મળે ત્યારે આદર્શ. બલ્ક ચૂકવણી ફોર્મ પર જાઓ, ભાડૂઆત દીઠ રકમ દાખલ કરો અને એકસાથે બધું સાચવો.',
    'docs_pay_cash' => 'ભૌતિક રોકડ ચૂકવણી',
    'docs_pay_cheque' => 'બેંક ચેક અથવા કેશિયર્સ ચેક',
    'docs_pay_gateway' => 'એકીકૃત ગેટવે દ્વારા ઓનલાઇન ચૂકવણી',
    'docs_pay_history' => 'ચૂકવણી ઇતિહાસ',
    'docs_pay_history_desc' => 'ભાડૂઆત દીઠ, પ્રોપર્ટી દીઠ અથવા સિસ્ટમ-વ્યાપી ચૂકવણી ઇતિહાસ જુઓ. તારીખ શ્રેણી, ચૂકવણી પદ્ધતિ અથવા સ્થિતિ પ્રમાણે ફિલ્ટર કરો. એકાઉન્ટિંગ માટે CSV માં નિકાસ કરો.',
    'docs_pay_intro' => 'Payments મોડ્યુલ ભાડા સંગ્રહ, ચૂકવણી નોંધણી, રસીદ જનરેશન અને ચૂકવણી ઇતિહાસ ટ્રેકિંગને સંભાળે છે.',
    'docs_pay_methods' => 'ચૂકવણી પદ્ધતિઓ',
    'docs_pay_mobile' => 'M-Pesa, Airtel Money, Tigo Pesa',
    'docs_pay_receipts' => 'રસીદ જનરેશન',
    'docs_pay_receipts_desc' => 'રસીદો ક્રમિક ક્રમાંક સાથે આપોઆપ બને છે. દરેક રસીદમાં ભાડૂઆત માહિતી, ચૂકવણી રકમ, આવરી લેવાયેલ સમયગાળો અને ચૂકવણી પદ્ધતિ સામેલ છે. તમે PDF તરીકે ડાઉનલોડ કરી શકો, પ્રિન્ટ કરી શકો અથવા WhatsApp દ્વારા મોકલી શકો છો.',
    'docs_pay_record' => 'ચૂકવણી નોંધવી',
    'docs_pay_reversal' => 'ચૂકવણી પરત કરવી',
    'docs_pay_reversal_desc' => 'જો ચૂકવણી ખોટી રીતે નોંધાઈ હોય, તો તમે તેને પરત કરી શકો છો. પરત કરેલી ચૂકવણીઓને એ રીતે ચિહ્નિત કરવામાં આવે છે અને અહેવાલોમાંથી બાકાત રાખવામાં આવે છે. મૂળ રેકોર્ડ ઓડિટ હેતુ માટે સાચવવામાં આવે છે.',
    'docs_pay_step1' => '<strong>Payments</strong> પર જાઓ અને <strong>Record Payment</strong> પર ક્લિક કરો',
    'docs_pay_step2' => 'ભાડૂઆત (અથવા યુનિટ) પસંદ કરો',
