    'docs_prop_pay_inst' => 'ચૂકવણી સૂચનાઓ',
    'docs_prop_pay_inst_desc' => 'કેવી રીતે ચૂકવણી કરવી તે વિશે ભાડૂઆતોને બતાવેલ કસ્ટમ ટેક્સ્ટ',
