    'docs_set_company_desc' => 'રસીદો અને દસ્તાવેજો પર પ્રદર્શિત તમારી કંપની માહિતી અપડેટ કરો:',
    'docs_set_intro' => 'તમારી સિસ્ટમ પસંદગીઓ રૂપરેખાંકિત કરો, વપરાશકર્તાઓ અને ભૂમિકાઓનું સંચાલન કરો, અને બેકઅપ/નિકાસ કામગીરી સંભાળો.',
    'docs_set_late' => 'મોડી ફી સેટિંગ્સ',
    'docs_set_late_desc' => 'સિસ્ટમ-વ્યાપી મોડી ફી ડિફોલ્ટ્સ સેટ કરો: ફી પ્રકાર (ટકાવારી અથવા નિશ્ચિત), ગ્રેસ પિરિયડ અને મહત્તમ મર્યાદા. આને પ્રોપર્ટી દીઠ ઓવરરાઇડ કરી શકાય છે.',
