    'docs_set_payment' => 'ચૂકવણી સેટિંગ્સ',
    'docs_set_payment_desc' => 'કઈ ચૂકવણી પદ્ધતિઓ ઉપલબ્ધ છે, રસીદ ક્રમાંકન ઉપસર્ગ અને ભાડૂઆતોને બતાવેલ ચૂકવણી સૂચનાઓ રૂપરેખાંકિત કરો.',
