    'docs_tp_note' => 'ટેનન્ટ પોર્ટલ એ ફક્ત-વાંચન ઇન્ટરફેસ છે. ભાડૂઆતો તેમની માહિતી જોઈ શકે છે પરંતુ લીઝ શરતોમાં ફેરફાર કરી શકતા નથી અથવા ચૂકવણીઓ નોંધી શકતા નથી.',
    'docs_tp_pay_history' => 'ચૂકવણી ઇતિહાસ',
