    'docs_tp_profile_mgmt' => 'પ્રોફાઇલ સંચાલન',
    'docs_tp_profile_mgmt_desc' => 'ફોન નંબર, ઇમેઇલ અને કટોકટી સંપર્ક માહિતી અપડેટ કરો',
    'docs_tpl_access' => 'પોર્ટલ ઍક્સેસ કરવું',
