    'docs_tpl_intro' => 'ભાડૂઆતો Tenant Portal ને કેવી રીતે ઍક્સેસ કરે છે.',
    'docs_tpl_password' => 'પાસવર્ડ',
    'docs_tpl_password_desc' => 'તમારા મકાનમાલિક દ્વારા અથવા નોંધણી દરમિયાન સેટ કરેલ',
    'docs_tpl_security' => 'તમારા લોગિન ઓળખપત્રો સુરક્ષિત રાખો. તમારો પાસવર્ડ અન્ય લોકો સાથે શેર કરશો નહીં. જો તમને અનધિકૃત ઍક્સેસની શંકા હોય, તો તરત જ તમારા મકાનમાલિકનો સંપર્ક કરો.',
    'docs_tpl_step1' => 'તમારા મકાનમાલિક દ્વારા આપવામાં આવેલ ટેનન્ટ પોર્ટલ URL ખોલો',
    'docs_tpl_step2' => 'તમારો ફોન નંબર અથવા ઇમેઇલ સરનામું દાખલ કરો',
    'docs_tpl_step3' => 'તમારો પાસવર્ડ દાખલ કરો',
