    'docs_tpp_balance' => 'વર્તમાન બેલેન્સ',
    'docs_tpp_balance_desc' => 'તમારું ડેશબોર્ડ કોઈપણ બાકી ભાડું અને મોડી ફી સહિત તમારું વર્તમાન બેલેન્સ બતાવે છે. જેમ તમારા મકાનમાલિક દ્વારા ચૂકવણીઓ નોંધાય છે તેમ બેલેન્સ રીઅલ-ટાઇમમાં અપડેટ થાય છે.',
