    'docs_tpp_intro' => 'Tenant Portal પરથી તમારો ચૂકવણી ઇતિહાસ જુઓ અને રસીદો ડાઉનલોડ કરો.',
    'docs_tpp_next_due' => 'આગામી ચૂકવણી નિયત',
    'docs_tpp_next_due_desc' => 'ડેશબોર્ડ સ્પષ્ટપણે બતાવે છે કે તમારી આગામી ચૂકવણી ક્યારે નિયત છે અને કેટલી. મોડી ફી ટાળવા સમયસર ચૂકવો.',
