    'intro_go_statements' => 'નાણાકીય પત્રકો',
    'intro_go_journal' => 'રોજમેળ',
    'intro_go_tb' => 'કાચું સરવૈયું',
    'intro_go_aged' => 'બાકીની ઉંમર',
    'intro_properties_index_what' => 'તમે સંભાળતા દરેક મકાન. મિલકતમાં યુનિટ હોય છે, અને બાકી બધું — ભાડૂત, લીઝ, ભાડું — તે યુનિટ પર આધારિત છે.',
    'intro_properties_index_how' => 'નવી સિસ્ટમમાં અહીંથી શરૂ કરો. મિલકત ઉમેરો, પછી તેના યુનિટ ઉમેરો. યુનિટ, ફોટા અને ખર્ચ જોવા કોઈપણ મિલકત પર ક્લિક કરો.',
    'intro_properties_create_what' => 'મકાન ઉમેરો. ફક્ત નામ જરૂરી છે — બાકી પછી ભરી શકાય.',
    'intro_properties_create_how' => 'એવું નામ આપો જે લોકો રિપોર્ટમાં ઓળખે. સાચવ્યા પછી યુનિટ ઉમેરો.',
    'intro_properties_view_what' => 'એક મિલકત વિશે બધું: તેના યુનિટ, કેટલા ભરેલા, ફોટા અને ખર્ચ.',
    'intro_properties_view_how' => 'યુનિટ, ફોટા અને ખર્ચ વચ્ચે જવા ટેબ વાપરો. લીઝ શરૂ અને પૂરી થતાં ઓક્યુપન્સી જાતે અપડેટ થાય છે.',
    'intro_units_index_what' => 'તમારી મિલકતોમાં દરેક ભાડે આપી શકાય તેવી જગ્યા, તેના ભાડા અને ભરાયેલી છે કે નહીં તે સાથે.',
    'intro_units_index_how' => 'લીઝ બનાવતાં યુનિટ આપોઆપ ભરાયેલું થાય છે, અને લીઝ પૂરી થતાં ખાલી. ભાડું અહીં સેટ કરો — નવી લીઝ તેને ડિફૉલ્ટ તરીકે લે છે.',
    'intro_units_create_what' => 'મિલકતમાં ભાડે આપી શકાય તેવી જગ્યા ઉમેરો — ફ્લેટ, રૂમ, દુકાન કે ઓફિસ.',
    'intro_units_create_how' => 'અહીં સેટ કરેલું ભાડું અને ચલણ આ યુનિટ પર લીઝ બનાવતાં ડિફૉલ્ટ બને છે. સ્થિતિ ખાલી રહેવા દો; લીઝ શરૂ થતાં તે જાતે બદલાય છે.',
    'intro_units_view_what' => 'એક યુનિટ: તેની હાલની લીઝ, ભાડું, ફોટા અને ઇતિહાસ.',
    'intro_units_view_how' => 'જો યુનિટ ભરાયેલું દેખાય પણ કોઈ લીઝ ન હોય, તો જૂની લીઝ મુક્ત કર્યા વગર દૂર થઈ છે — યુનિટની સ્થિતિ સંપાદિત કરી સુધારો.',
    'intro_tenants_index_what' => 'તમારી પાસેથી ભાડે લેનારા બધા, ભૂતકાળ અને વર્તમાન.',
    'intro_tenants_index_how' => 'લીઝ પર મૂકતાં પહેલાં ભાડૂત નોંધો. લીઝ, ચુકવણી, દસ્તાવેજો અને ઓળખપત્ર જોવા નામ પર ક્લિક કરો.',
    'intro_tenants_create_what' => 'કોઈને નોંધો જેથી તેને લીઝ પર મૂકી શકાય.',
    'intro_tenants_create_how' => 'ફક્ત નામ અને ફોન જરૂરી છે. TIN, નજીકના સગા અને નોકરી હમણાં કે પછી ઉમેરી શકાય — ઓળખપત્ર સાચવ્યા પછી ભાડૂત પૃષ્ઠથી અપલોડ થાય છે.',
    'intro_tenants_view_what' => 'એક ભાડૂત: તેની લીઝ, ચૂકવેલું, બાકી, દસ્તાવેજો અને ઓળખ.',
    'intro_tenants_view_how' => 'જમણી બાજુના ઓળખ દસ્તાવેજ કાર્ડમાં ઓળખપત્ર અપલોડ કરો. બાકી બધા માટે — કરાર, પત્રવ્યવહાર, સંદર્ભ — દસ્તાવેજ ટેબ વાપરો.',
    'intro_tenants_edit_what' => 'ભાડૂતની વિગતો બદલો.',
    'intro_tenants_edit_how' => 'ઓળખપત્ર અહીં નથી — તે ભાડૂતના પોતાના પૃષ્ઠથી સંભાળાય છે, કારણ કે તે ફાઇલ છે, ફીલ્ડ નહીં.',
    'intro_leases_index_what' => 'ભાડૂતને યુનિટ સાથે જોડતો દરેક કરાર, તેના ભાડા, મુદત અને ચુકવણી આવૃત્તિ સાથે.',
    'intro_leases_index_how' => 'લીઝ જ ભાડું વસૂલવાનું શરૂ કરે છે. જ્યાં સુધી યુનિટ પર સક્રિય લીઝ ન હોય, ન બિલ બને ન બાકી દેખાય.',
    'intro_leases_create_what' => 'સંમત શરતો પર ભાડૂતને યુનિટમાં મૂકો.',
    'intro_leases_create_how' => 'યાદીમાં ફક્ત ખાલી કે અનામત યુનિટ દેખાય છે — યુનિટ ગુમ હોય તો તે જૂની લીઝથી ભરાયેલું ચિહ્નિત છે. ભાડું અને થાપણ યુનિટમાંથી ભરાય છે, અને ચુકવણી આવૃત્તિ નક્કી કરે છે કે ભાડું કેટલી વાર લાગશે.',
    'intro_leases_view_what' => 'એક લીઝ: તેની શરતો, તેની સામે ચૂકવેલું, અને દસ્તાવેજો.',
    'intro_leases_view_how' => 'શરૂઆતની તારીખથી દર સમયગાળે ભાડું આપોઆપ લાગે છે. સહી કરી શકાય તેવા કરાર માટે પ્રિન્ટ વાપરો.',

    // Page introductions, money and ledger pages (part 35b)
    'intro_payments_index_what' => 'મળેલી દરેક ચુકવણી, અને તેની રસીદો.',
    'intro_payments_index_how' => 'ચુકવણી પહેલા સૌથી જૂના બાકી ચાર્જ ભરે છે. અંશતઃ ચૂકવો તો બાકી રહે છે — અંશતઃ ચુકવણીને શૂન્ય ગણાતી નથી.',
    'intro_payments_create_what' => 'ભાડૂત પાસેથી મળેલા નાણાં નોંધો.',
    'intro_payments_create_how' => 'ચુકવણીની રીત પસંદ કરો: રોકડ અને ચેક બેંકમાં જમા કરો ત્યાં સુધી તમારી પાસે રહે છે, જ્યારે બેંક ટ્રાન્સફર સીધા બેંકમાં જાય છે. રકમ આપોઆપ સૌથી જૂના બાકી પર લાગે છે.',
    'intro_payments_view_what' => 'એક ચુકવણી: તેણે શું ભર્યું, તેની રસીદ, અને જોડાયેલા દસ્તાવેજો.',
    'intro_payments_view_how' => 'ચુકવણી ઉલટાવતાં તેણે ભરેલા ચાર્જ ફરી ખૂલે છે, અને ભાડૂતનું બાકી પહેલા જેવું થાય છે.',
    'intro_deposits_index_what' => 'તમારી પાસે રહેલી સિક્યોરિટી થાપણો, અને તેમનું શું થયું.',
    'intro_deposits_index_how' => 'થાપણ ભાડૂતના નાણાં છે જ્યાં સુધી જપ્ત ન થાય, તેથી તે કમાયેલી નહીં પણ રાખેલી છે. પરત કે જપ્તી માટે બીજી વ્યક્તિની મંજૂરી જોઈએ.',
    'intro_deposits_create_what' => 'લીઝ સામે મળેલી થાપણ નોંધો.',
    'intro_deposits_create_how' => 'રોકડ ભાડાની ચુકવણી જેવી જ તમારી પાસે આવે છે. થાપણ ભાડૂત માટે રાખેલા નાણાં તરીકે નોંધાય છે, આવક તરીકે નહીં.',
    'intro_deposits_view_what' => 'એક થાપણ: કેટલું રાખેલું, કપાત, અને પરતની સ્થિતિ.',
    'intro_deposits_view_how' => 'પરત કરતાં પહેલાં કપાત વિગતવાર નોંધો. પરત અને જપ્તી તરત થતી નથી, વિનંતી બનાવે છે — બીજું કોઈ ખાતાવહી, ચૂકવવાપાત્ર હેઠળ મંજૂર કરે છે.',
    'intro_expenses_index_what' => 'મિલકતો ચલાવવાનો ખર્ચ — વીજળી, પગાર, સમારકામ.',
    'intro_expenses_index_how' => 'બિલ આવતાં જ નોંધો, ચૂકવ્યું હોય કે નહીં. ખર્ચ તે મહિનામાં ગણાય જેમાં થયો, અને ચુકવણી મંજૂર થાય ત્યાં સુધી બાકી રહે છે.',
    'intro_ledger_index_what' => 'તમારી ખાતાની યાદી — બેંક ખાતાં, રોકડ પેટીઓ, અને આવક-ખર્ચ શ્રેણીઓ જેની સામે બધું નોંધાય છે.',
    'intro_ledger_index_how' => 'ચુકવણી નોંધતાં પહેલાં આ સેટ કરો. બેંક ખાતાં ઉમેરો, પછી ડિફૉલ્ટ બેંક જોડો જેથી ટ્રાન્સફરને ગંતવ્ય ખબર પડે. સિસ્ટમ ચિહ્નિત ખાતાં આપોઆપ બને છે અને કાઢી શકાતાં નથી.',
    'intro_ledger_mappings_what' => 'સ્વયંસંચાલિત નોંધ ક્યાં જાય છે. દરેક ઘટના — ભાડું, થાપણ, બેંક ટ્રાન્સફર — એક ખાતા તરફ નિર્દેશ કરે છે.',
    'intro_ledger_mappings_how' => 'હાઇલાઇટ પંક્તિઓ હજી જોડાયેલી નથી અને તે ઘટનાઓ નોંધાય તે પહેલાં સેટ કરવી જરૂરી છે. નીચે ચોપડા બંધ કરવાથી તે તારીખે કે પહેલાં કંઈ નોંધાતું નથી.',
    'intro_ledger_charges_what' => 'ભાડૂતોનું બાકી: બાકી થતાં ભાડું, યુટિલિટી અને વિલંબ ફી.',
    'intro_ledger_charges_how' => 'દરેક સક્રિય લીઝ માટે દર સમયગાળે ચાર્જ આપોઆપ બને છે. જો આ ખાલી હોય, તો દૈનિક જનરેટર હજી ચાલ્યું નથી — ચાર્જ વગર કોઈ બાકી નથી.',
    'intro_ledger_floats_what' => 'તમારા લોકો કંપની વતી રાખેલી રોકડ, અને તેમણે જાહેર કરેલી જમા.',
    'intro_ledger_floats_how' => 'કોઈ પહેલી વાર રોકડ ચુકવણી નોંધે ત્યારે રોકડ સિલક જાતે બને છે. નાણાં બેંકે પહોંચે ત્યારે બેંકમાં જમા કરો વાપરો — બીજી વ્યક્તિ મંજૂર કરે પછી જ સિલક ઘટે છે.',
    'intro_ledger_payables_what' => 'ચુકવણી કે મંજૂરીની રાહ જોતું બધું: સપ્લાયર બિલ, અને સહકર્મીએ માંગેલી થાપણ પરત.',
    'intro_ledger_payables_how' => 'મંજૂરીથી જ નાણાં ખરેખર બહાર જાય છે. તમે તમારી પોતાની વિનંતી મંજૂર કરી શકતા નથી, તેથી ઓછામાં ઓછા બે લોકોને મંજૂરી અધિકાર જોઈએ.',
    'intro_ledger_journal_what' => 'ચોપડામાં દરેક નોંધ, વ્યક્તિએ કરી હોય કે સિસ્ટમે.',
    'intro_ledger_journal_how' => 'મંજૂરીની રાહ જોતી નોંધો કંઈ અસર કરતી નથી. પોસ્ટ થયેલી નોંધો ક્યારેય સંપાદિત થતી નથી — ભૂલ ઉલટાવીને સુધારો, બંને રેકોર્ડ પર રહે છે.',
    'intro_ledger_create_what' => 'હાથે તે નોંધો જે સિસ્ટમ જાતે કાઢી શકતી નથી — શરૂઆતની બાકી, સુધારો, કે ગોઠવણ.',
    'intro_ledger_create_how' => 'સબમિટ કરતાં પહેલાં ઉધાર અને જમા સરખા હોવા જોઈએ, અને દરેક લીટી એક જ ચલણનું ખાતું વાપરે. પછી બીજું કોઈ મંજૂર કરે છે.',
    'intro_ledger_view_what' => 'એક નોંધ, તેની લીટીઓ, અને કોણે બનાવી અને મંજૂર કરી.',
    'intro_ledger_view_how' => 'પોસ્ટ થયેલી નોંધ સંપાદિત કે કાઢી શકાતી નથી. અરીસા નોંધથી રદ કરવા ઉલટાવો વાપરો — મૂળ દેખાતી રહે છે, ઉલટાવેલી ચિહ્નિત.',
    'intro_ledger_trial-balance_what' => 'આરોગ્ય તપાસ: કુલ ઉધાર સામે કુલ જમા, દરેક ચલણ માટે.',
    'intro_ledger_trial-balance_how' => 'આ સરખા હોવા જોઈએ. દરેક નોંધ સાચવતી વખતે ચકાસાય છે, તેથી ફરક હોય તો કંઈકે એપ્લિકેશન બહાર ડેટાબેઝ બદલ્યો છે.',
    'intro_ledger_statements_what' => 'નફો-નુકસાન, સરવૈયું, એકમવાર નફાકારકતા, અને કોણ ચુકવણીમાં પાછળ છે.',
    'intro_ledger_statements_how' => 'દરેક આંકડો લિંક છે — ખાતા સુધી, પછી તેની પાછળની નોંધો સુધી ક્લિક કરો. આવક બાકી થતાં અને ખર્ચ થતાં ગણાય છે, રોકડ ફરે ત્યારે નહીં.',
    'intro_ledger_account_what' => 'એક ખાતા પરની દરેક હિલચાલ, ચાલુ બાકી સાથે.',
    'intro_ledger_account_how' => 'અહીં પત્રકનો આંકડો સમજાવાય છે. દરેક નોંધ નંબર તે પૂરી નોંધ સાથે જોડાય છે જ્યાંથી તે આવ્યો.',

    // Page introduction links (part 35c)
    'intro_go_deposits' => 'થાપણો',
    'intro_go_deductions' => 'કપાત',
    'intro_go_expenses' => 'ખર્ચ',
    'intro_go_inquiries' => 'પૂછપરછ',
    'intro_go_users' => 'વપરાશકર્તાઓ',
    // Page introductions — batch 2 (part 35d)
    'intro_properties_edit_what' => 'મિલકતની વિગતો બદલો.',
    'intro_properties_edit_how' => 'નામ બદલવાથી દરેક રિપોર્ટ અને પત્રકમાં તે કેવું વંચાય છે તે બદલાય છે, જૂનાં પણ.',
    'intro_properties_photos_what' => 'મકાનની તસવીરો — ખાલી જગ્યાની જાહેરાત અને સ્થિતિની નોંધ માટે ઉપયોગી.',
    'intro_properties_photos_how' => 'અહીંની તસવીરો આખી મિલકત દર્શાવે છે. કોઈ એક ફ્લેટની તસવીરો તે એકમ પર મૂકો.',
    'intro_properties_settings_what' => 'ફક્ત આ મિલકતને લાગુ પડતા નિયમો, જેમ કે તેનું ભાડા ચક્ર અને વિલંબ ફીની શરતો.',
    'intro_properties_settings_how' => 'અહીં જે પણ ગોઠવાય તે ફક્ત આ મિલકત માટે સિસ્ટમની સામાન્ય ગોઠવણને બદલે છે. સામાન્ય નિયમ ચાલુ રાખવા ખાનું ખાલી રહેવા દો.',
    'intro_units_edit_what' => 'એકમની વિગતો કે તેનું ભાડું બદલો.',
    'intro_units_edit_how' => 'ભાડું બદલવાથી ચાલુ કરારો બદલાતા નથી — તેમાં સહી વખતે નક્કી થયેલી રકમ જ રહે છે. જે વસૂલાય છે તે બદલવા કરારમાં જ ભાડું બદલો.',
    'intro_units_photos_what' => 'આ એકમની તસવીરો, જાહેરાત માટે અને તેની સ્થિતિ નોંધવા માટે.',
    'intro_units_photos_how' => 'આ પ્રવેશ અને નિકાસ વખતે લો; ડિપોઝિટ અંગેના મોટા ભાગના ઝઘડા શરૂ થાય તે પહેલાં જ પતી જાય છે.',
    'intro_leases_edit_what' => 'ચાલુ કરારની શરતો બદલો.',
    'intro_leases_edit_how' => 'ભાડું કે આવર્તન બદલવાની અસર હવે પછી ઊભા થતા ચાર્જ પર પડે છે. અગાઉ ઊભા થયેલા ચાર્જ મૂળ રકમ જ રાખે છે — ખોટા હોય તો તેમને ઉલટાવો.',
    'intro_leases_templates_what' => 'ભાડા કરાર છાપતી વખતે વપરાતું લખાણ.',
    'intro_leases_templates_how' => '{{rent_amount}} જેવા પ્લેસહોલ્ડર છાપતી વખતે કરારમાંથી ભરાઈ જાય છે. એકને ડિફોલ્ટ ગણાવો અને નવા કરારો તે વાપરશે.',
    'intro_deposits_edit_what' => 'પહેલેથી નોંધાયેલી ડિપોઝિટની વિગતો સુધારો.',
    'intro_deposits_edit_how' => 'પરત આપવી કે જપ્ત કરવી અહીં થતું નથી — તે ડિપોઝિટના પોતાના પાના પરથી માગવામાં આવે છે અને તેને મંજૂરી જોઈએ.',
    'intro_payments_edit_what' => 'પહેલેથી નોંધાયેલી ચુકવણીની વિગતો સુધારો.',
    'intro_payments_edit_how' => 'ચુકવણી સંપૂર્ણ રદ કરવા તેને તેના પોતાના પાના પરથી ઉલટાવો — તેથી તેણે ભરેલા ચાર્જ ફરી ખૂલે છે અને હિસાબમાંથી પણ તે નીકળી જાય છે.',
    'intro_payments_bulk_what' => 'એકસાથે અનેક ચુકવણી નોંધો, ભાડાના દિવસે લાઇન લાગે ત્યારે.',
    'intro_payments_bulk_how' => 'દરેક હરોળ તે ભાડૂતના સૌથી જૂના બાકી ચાર્જ પર લાગે છે, બરાબર એક જ ચુકવણીની જેમ.',
    'intro_deposits_late-fees_what' => 'ભાડું સમયસર ન ભરાય ત્યારે ઉમેરાતી ફી.',
    'intro_deposits_late-fees_how' => 'આ તમારા વિલંબ ફીના નિયમો પ્રમાણે રોજની પ્રક્રિયા દ્વારા આપોઆપ લાગે છે. કારણ નોંધીને ફી માફ કરી શકાય છે.',
    'intro_deposits_late-fee-settings_what' => 'વિલંબ ફી ક્યારે લાગશે અને કેટલી હશે તે નક્કી કરતા નિયમો.',
    'intro_deposits_late-fee-settings_how' => 'છૂટનો સમય રાખો જેથી એક દિવસ મોડી આવેલી ચુકવણી પર દંડ ન લાગે, અને ઉપલી મર્યાદા રાખો જેથી લાંબા સમયના બાકી ખાતા પર ફી બેકાબૂ ન બને.',
    'intro_documents_index_what' => 'સિસ્ટમમાં સાચવેલી દરેક ફાઇલ, અને દરેક કોની સાથે જોડાયેલી છે.',
    'intro_documents_index_how' => 'શ્રેણી પ્રમાણે અથવા દસ્તાવેજ જેની સાથે જોડાયેલો છે તે પ્રમાણે ગાળો. ગુપ્ત તરીકે નિશાની કરેલી ફાઇલો પર નિશાની દેખાય છે, પણ આ પાનું ખોલી શકનાર દરેકને તે દેખાય છે.',
    'intro_documents_upload_what' => 'ફાઇલ ઉમેરો અને તેને મિલકત, એકમ, ભાડૂત, કરાર, ચુકવણી, ડિપોઝિટ કે ખર્ચ સાથે જોડો.',
    'intro_documents_upload_how' => 'કોઈ નોંધ પરથી અહીં આવો ત્યારે તે પહેલેથી પસંદ થયેલી મળે છે, અને સાચી જગ્યાએ ફાઇલ મૂકવાનો એ જ સૌથી ભરોસાપાત્ર રસ્તો છે.',
    'intro_documents_view_what' => 'એક દસ્તાવેજ: શક્ય હોય ત્યાં ઝલક, અને તે કોની સાથે જોડાયેલો છે.',
    'intro_documents_view_how' => 'બ્રાઉઝર જે બતાવી ન શકે તે માટે ડાઉનલોડ વાપરો. સંપાદન નોંધ બદલે છે, ફાઇલ નહીં — ફાઇલ બદલવા ફરી અપલોડ કરો.',
    'intro_inspections_index_what' => 'એકમોની સ્થિતિની તપાસ — પ્રવેશ, નિકાસ કે નિયમિત.',
    'intro_inspections_index_how' => 'નિકાસ તપાસ જ ડિપોઝિટમાંથી કપાતને વાજબી ઠેરવે છે, તેથી કોઈ પણ ડિપોઝિટ પરત આપતાં પહેલાં તે કરી લો.',
    'intro_inspections_create_what' => 'કોઈ એકમની સ્થિતિની તપાસ શરૂ કરો.',
    'intro_inspections_create_how' => 'તૈયાર યાદી મેળવવા ટેમ્પ્લેટ પસંદ કરો. પછીથી જેના પૈસા માગી શકો તે દરેક વસ્તુની તસવીર લો.',
    'intro_inspections_view_what' => 'એક તપાસ: તપાસેલી દરેક બાબત, તેની સ્થિતિ અને તેની તસવીરો.',
    'intro_inspections_view_how' => 'નુકસાન તરીકે નિશાની કરેલી બાબતોને ડિપોઝિટની કપાતમાં ફેરવી શકાય છે, તેમની વિગત અને તસવીરો સાથે.',
    'intro_inspections_move-out_what' => 'ભાડૂત જાય ત્યારે થતી તપાસ, જેમાં એકમની સરખામણી તેને જે હાલતમાં મળ્યું હતું તેની સાથે થાય છે.',
    'intro_inspections_move-out_how' => 'ડિપોઝિટ પરત આપતાં પહેલાં આ પૂરી કરો — તેના વગર કરેલી કપાતનો બચાવ કરવો અઘરો છે.',
    'intro_inspections_deductions_what' => 'નુકસાન કે સફાઈ પેટે ડિપોઝિટમાંથી રોકી રાખેલી રકમ.',
    'intro_inspections_deductions_how' => 'દરેક કપાત તપાસમાં મળેલી કોઈ બાબત પર આધારિત હોવી જોઈએ. કપાત પછી જે બચે તે જ પરત અપાય છે.',
    'intro_inspections_templates_what' => 'ફરી વાપરી શકાય તેવી યાદીઓ, જેથી દરેક તપાસમાં એ જ બાબતો આવરી લેવાય.',
    'intro_inspections_templates_how' => 'દરેક પ્રકારની મિલકત માટે એક બનાવો. એકસરખી યાદી જ બે તપાસને સરખાવવા યોગ્ય બનાવે છે.',
    'intro_maintenance_index_what' => 'સમારકામ અને જાળવણીની અરજીઓ, નોંધાયાથી પૂરી થાય ત્યાં સુધી.',
    'intro_maintenance_index_how' => 'ભાડૂતો પોતાના પોર્ટલ પરથી આ મૂકી શકે છે. કારીગર સોંપો, ખર્ચ પર નજર રાખો, અને પૂરું થાય ત્યારે તે ખર્ચ બની શકે છે.',
    'intro_maintenance_create_what' => 'જે વસ્તુ સુધારવાની છે તે નોંધો.',
    'intro_maintenance_create_how' => 'તસવીરો અને સ્પષ્ટ વર્ણન બીજી મુલાકાત બચાવે છે. અગ્રતા પ્રામાણિકપણે નક્કી કરો — બધું જ તાત્કાલિક હોય તો કશું તાત્કાલિક રહેતું નથી.',
    'intro_maintenance_view_what' => 'એક અરજી: તેનો ઇતિહાસ, તસવીરો, કોને સોંપાઈ અને કેટલો ખર્ચ થયો.',
    'intro_maintenance_view_how' => 'અહીં નોંધેલા ખર્ચને ખર્ચમાં ફેરવી શકાય છે, અને એ જ તેને હિસાબમાં લાવે છે.',
    'intro_maintenance_edit_what' => 'જાળવણી અરજીની વિગતો બદલો.',
    'intro_maintenance_edit_how' => 'સ્થિતિ સુધારવી એ જ ભાડૂતને જણાવે છે કે કંઈક ચાલી રહ્યું છે, જો તેણે પોર્ટલ પરથી અરજી કરી હોય તો.',
    'intro_maintenance_contractors_what' => 'સમારકામ માટે તમે જેમને બોલાવો છો તે લોકો અને પેઢીઓ.',
    'intro_maintenance_contractors_how' => 'અહીં કામ અને દર નોંધવાથી કામ સોંપવું ઝડપી બને છે અને ખર્ચ વધે ત્યારે સરખામણી માટે કંઈક મળે છે.',
    'intro_maintenance_reports_what' => 'જાળવણીનો ખર્ચ કેટલો થાય છે — મિલકત, શ્રેણી અને કારીગર પ્રમાણે.',
    'intro_maintenance_reports_how' => 'જોઈએ તેના કરતાં વધુ ખર્ચ કરાવતું મકાન, કે વારંવાર થતી ખરાબી જે સુધારવાને બદલે ઢાંકી દેવાય છે, તે શોધવા આ વાપરો.',
    'intro_utilities_index_what' => 'પાણી, વીજળી અને ભાડૂતો પાસેથી વસૂલાતી બીજી સેવાઓ.',
    'intro_utilities_index_how' => 'મીટર રીડિંગ નોંધો, અને તમારા દર પ્રમાણે રકમ ગણાઈને તે ભાડૂતના બાકીમાં ઉમેરાય છે.',
    'intro_utilities_readings_what' => 'મીટર રીડિંગ, અને તેમાંથી ગણાયેલા ચાર્જ.',
    'intro_utilities_readings_how' => 'હાલનું રીડિંગ ભરો; વપરાશ એટલે ગયા વખત કરતાં તફાવત. નવા ભાડાનું પહેલું રીડિંગ ધ્યાનથી ચકાસો — પછીનું બધું તેના પર જ આધારિત છે.',
    'intro_utilities_types_what' => 'તમે જે સેવાઓનું બિલ બનાવો છો, અને દરેકનો દર કેવી રીતે નક્કી થાય છે.',
    'intro_utilities_types_how' => 'મીટરવાળા પુરવઠા માટે પ્રતિ-એકમ પસંદ કરો, નિશ્ચિત માસિક ખર્ચ માટે સપાટ, અને વપરાશ સાથે દર બદલાય ત્યાં તબક્કાવાર.',
    'intro_vacancies_index_what' => 'તમે જેની જાહેરાત કરી રહ્યા છો તે ખાલી એકમો, અને તેમના પર આવેલી પૂછપરછ.',
    'intro_vacancies_index_how' => 'ફક્ત ખાલી એકમો જ યાદીમાં મૂકી શકાય. તે એકમ પર કરાર બનતાં જ યાદી આપોઆપ બંધ થાય છે.',
    'intro_vacancies_create_what' => 'ખાલી એકમની જાહેરાત કરો.',
    'intro_vacancies_create_how' => 'ભાડું અને વર્ણન એકમમાંથી આવે છે. તસવીરો ઉમેરો — તસવીર વગરની જાહેરાતને ઘણી ઓછી પૂછપરછ મળે છે.',
    'intro_vacancies_view_what' => 'એક જાહેરાત: તે કેવી વંચાય છે, અને કોણે તેના વિશે પૂછ્યું છે.',
    'intro_vacancies_view_how' => 'આશાસ્પદ પૂછપરછને ભાડૂત બનાવો, પછી કરાર — તેથી જાહેરાત આપોઆપ બંધ થાય છે.',
    'intro_vacancies_inquiries_what' => 'જેમણે ખાલી એકમ વિશે પૂછ્યું છે તે લોકો.',
    'intro_vacancies_inquiries_how' => 'દરેકને સંપર્ક કર્યો કે બંધ એવી નિશાની કરો જેથી કોઈને બે વાર ન પૂછાય કે કોઈ ભુલાઈ ન જાય.',
    'intro_reports_index_what' => 'કામકાજના અહેવાલો — વસૂલાત, ભરાવો અને બાકી.',
    'intro_reports_index_how' => 'આ તમારી રોજિંદી નોંધો વાંચે છે. હિસાબ માટે તેના બદલે લેજરનાં પત્રકો વાપરો.',
    'intro_reports_financial_what' => 'એક ગાળામાં વસૂલ થયેલા અને વપરાયેલા નાણાં.',
    'intro_reports_financial_how' => 'આ રોકડને તે ફરી ત્યારે ગણે છે. લેજર હેઠળનું નફા-નુકસાન આવકને તે બાકી પડી ત્યારે ગણે છે, તેથી બંને જુદા સવાલોના જવાબ આપે છે.',
    'intro_reports_occupancy_what' => 'તમારી કેટલી જગ્યા કમાણી કરે છે, અને કેટલી ખાલી પડી છે.',
    'intro_reports_occupancy_how' => 'ભરાવો કરારની સ્થિતિ પ્રમાણે ચાલે છે, તેથી તે તમારા કરારો જેટલો જ સાચો છે. કરાર પૂરો થયા પછી પણ ભરેલું ગણાતું એકમ આ આંકડો વધારીને બતાવશે.',
    'intro_reports_custom_what' => 'તમને જોઈતા કૉલમ અને ગાળણ પસંદ કરીને તમારો પોતાનો અહેવાલ બનાવો.',
    'intro_reports_custom_how' => 'જેના પર ફરી કામ કરવું હોય કે આગળ મોકલવું હોય તે સ્પ્રેડશીટમાં નિકાસ કરો.',
    'intro_expenses_reports_what' => 'તમે શું ખર્ચ્યું, મિલકત અને શ્રેણી પ્રમાણે વહેંચીને.',
    'intro_expenses_reports_how' => 'ખર્ચ જે મહિનામાં થયો તે મહિનામાં ગણાય છે, તેથી મોડું ભરાયેલું બિલ પણ સાચા મહિનામાં જ આવે છે.',
    'intro_payments_gateway-transactions_what' => 'ઓનલાઇન ગેટવે મારફતે આવેલી ચુકવણીઓ.',
    'intro_payments_gateway-transactions_how' => 'આ પોતે જ નોંધાય છે અને સીધી બેંકમાં જાય છે, કારણ કે રોકડ કોઈના હાથમાં આવી નથી. અહીં નિષ્ફળ વ્યવહારનો અર્થ એ કે ભાડૂત પાસેથી પૈસા લેવાયા જ નથી.',
    'intro_payments_gateway-settings_what' => 'ઓનલાઇન ચુકવણી પૂરી પાડનાર જોડો જેથી ભાડૂતો જાતે ચૂકવી શકે.',
    'intro_payments_gateway-settings_how' => 'જાહેર કરતાં પહેલાં નાની સાચી ચુકવણીથી ચકાસો — ખોટી કૂંચી ભાડૂતના છેડે ચૂપચાપ નિષ્ફળ જાય છે.',
    'intro_payments_gateway-pay_what' => 'ઓનલાઇન ચૂકવતી વખતે ભાડૂતને દેખાતું પાનું.',
    'intro_payments_gateway-pay_how' => 'તેમને શું દેખાશે તે જોવા આ ખોલો. સફળ ચુકવણી પોતે નોંધાઈને તેમના સૌથી જૂના ચાર્જ ભરી દે છે.',
    'intro_settings_index_what' => 'કંપનીની વિગતો, ચલણ, મોડ્યુલ અને આખી સિસ્ટમના નિયમો.',
    'intro_settings_index_how' => 'મોડ્યુલ ટૅબ આખી સુવિધાઓ ચાલુ-બંધ કરે છે. કેટલીકને ઊંચી યોજના જોઈએ, અને તેમના પર નિશાની હોય છે.',
    'intro_settings_reminders_what' => 'આપોઆપ જતા સંદેશા જે ભાડૂતોને જણાવે છે કે શું બાકી છે અને શું મુદત વીતી ગઈ છે.',
    'intro_settings_reminders_how' => 'સ્મરણપત્રો ખરેખર બાકી હોય તે જ વાંચે છે, તેથી ભરી ચૂકેલા ભાડૂતને કદી પૂછાતું નથી. ચાલુ કરતાં પહેલાં ટેમ્પ્લેટ જાત પર અજમાવો.',
    'intro_settings_backup_what' => 'તમારો ડેટા નિકાસ કરો, અથવા બીજી સિસ્ટમમાંથી લાવો.',
    'intro_settings_backup_how' => 'કોઈ પણ મોટું કામ કરતાં પહેલાં નિકાસ લઈ લો — જથ્થાબંધ આયાત, ડેટાની સફાઈ, કે એવો ફેરફાર જેની ખાતરી ન હોય.',
    'intro_masters_users_what' => 'કોણ લોગ ઇન કરી શકે, અને દરેકને શું કરવાની છૂટ છે.',
    'intro_masters_users_how' => 'ઓછામાં ઓછા બે જણને મંજૂરીનો અધિકાર આપો — કોઈ પોતાનું જ કામ મંજૂર કરી શકતું નથી, તેથી એક જ મંજૂરી આપનાર હોય તો કશું કદી મંજૂર થશે નહીં.',
    'intro_masters_roles_what' => 'પરવાનગીઓના જૂથ જે નક્કી કરે છે કે વપરાશકર્તા શું જોઈ અને બદલી શકે.',
    'intro_masters_roles_how' => 'દરેક ભૂમિકાને જેટલું જરૂરી હોય તેટલું જ આપો. જે ચોકીદાર ચુકવણી કાઢી જ ન શકે તે તેને ભૂલથી પણ કાઢશે નહીં.',
    // Ledger documentation page (part 36)
    'docs_ledger_guide' => 'હિસાબી ખાતાવહી',
    'docs_led_intro' => 'આખી સિસ્ટમની પાછળ સંપૂર્ણ બે-બાજુ (ડબલ-એન્ટ્રી) ખાતાવહી ચાલે છે. ભાડું, ચુકવણી, ડિપોઝિટ અને ખર્ચ આપોઆપ તેમાં નોંધાતાં જાય છે, તેથી કોઈએ એક પણ જર્નલ નોંધ લખ્યા વગર તમારા ચોપડા સાચા રહે છે.',
    'docs_led_intro_note' => 'સિસ્ટમ વાપરવા માટે તમારે ડબલ-એન્ટ્રી હિસાબ સમજવાની જરૂર નથી. ચુકવણી અને ખર્ચ હંમેશની જેમ નોંધો; ખાતાવહી પોતાનું ધ્યાન જાતે રાખે છે. આ પાનું સમજાવે છે કે તે શું કરી રહી છે, અને એ થોડાં પાનાં જ્યાં તે તમારી પાસે કંઈક માગે છે.',
    'docs_led_ideas' => 'જાણવા જેવી ત્રણ વાતો',
    'docs_led_accrual' => 'ભાડું પહેલાં લેણું થાય છે, પછી ચૂકવાય છે',
    'docs_led_accrual_desc' => 'દર ગાળે ચાલુ દરેક કરાર માટે એક ચાર્જ ઊભો થાય છે. એ જ ક્ષણે ભાડું આવક બને છે અને એ જ ક્ષણે ભાડૂત પર દેવું ચઢે છે — તે પૈસા આપે ત્યારે નહીં. પછી કોઈ ચુકવણી એક કે વધુ ચાર્જ ભરે છે, સૌથી જૂનાથી શરૂ કરીને. એટલે જ બાકી રકમ ચોક્કસ રહે છે: આંશિક ચુકવણી દેવું બરાબર એટલું જ ઘટાડે છે જેટલું ભરાયું, અને એક મહિનાની વધારાની ચુકવણી હવે પછીના મહિનાની ઘટ છુપાવી શકતી નથી.',
    'docs_led_float' => 'કોઈના હાથમાં પડેલી રોકડ પર નજર રહે છે',
    'docs_led_float_desc' => 'જ્યારે કોઈ રોકડ વસૂલે છે ત્યારે તે સીધી બેંકમાં જતી નથી — તે કોઈ રોકડ પેટીમાં કે તેના ફ્લોટમાં જાય છે, એટલે કે કંપની વતી રખાયેલા પૈસા. બેંકમાં ભરે ત્યારે તે રવાનગી નોંધે છે. મંજૂરી આપનાર ખાતરી કરે પછી જ બાકી ઘટે છે. કોઈ પણ સમયે તમે જોઈ શકો છો કે શું અને ક્યાં રખાયું છે.',
    'docs_led_immutable' => 'નોંધાયેલી એન્ટ્રી કદી બદલાતી નથી',
    'docs_led_immutable_desc' => 'એન્ટ્રી એક વાર નોંધાઈ ગયા પછી તેને સંપાદિત કે રદ કરી શકાતી નથી. ભૂલ ઉલટી એન્ટ્રીથી સુધારાય છે, જે મૂળને રદ કરે છે અને બંને ચોપડે રહે છે. આ જ કારણે ગયા મહિને છાપેલું પત્રક આજે પણ સાચું છે.',
    'docs_led_setup' => 'તેને તૈયાર કરવી',
    'docs_led_setup_desc' => 'ખાતાવહી કંઈ પણ નોંધી શકે તે પહેલાં ચાર બાબતો, એક જ વાર:',
    'docs_led_s1' => '1. બે જણને મંજૂરીનો અધિકાર આપો',
    'docs_led_s1_desc' => 'સેટિંગ્સ &rsaquo; વપરાશકર્તાઓ, "ચુકવણી અને ડિપોઝિટ મંજૂર કરી શકે" પર નિશાની કરો. બે જણ જો તમે ઇચ્છો કે પૈસા બહાર જાય ત્યારે બીજી નજર પડે; એક પૂરતો છે જો તમે એકલા સિસ્ટમ ચલાવતા હો અને સ્વ-મંજૂરી ચાલુ રાખો.',
    'docs_led_s2' => '2. તમારાં ખાતાં બનાવો',
    'docs_led_s2_desc' => 'ખાતાવહી &rsaquo; ખાતાંની યાદી &rsaquo; નવું ખાતું. દરેક બેંક ખાતું ઉમેરો (પ્રકાર: સંપત્તિ, જાત: બેંક ખાતું), કોઈ પણ પરચૂરણ રોકડ પેટી, અને જે ખર્ચ ખાતાં પર તમે અહેવાલ ઇચ્છો છો તે — વીજળી, પગાર, સમારકામ.',
    'docs_led_s3' => '3. ડિફોલ્ટ બેંક જોડો',
    'docs_led_s3_desc' => 'ખાતાવહી &rsaquo; ખાતાં જોડાણ. "ડિફોલ્ટ બેંક ખાતું" વાળી હરોળ તમે ગોઠવો ત્યાં સુધી ઉજાગર રહે છે. જ્યાં સુધી તે સાચા ખાતા તરફ ન દર્શાવે ત્યાં સુધી બેંક ટ્રાન્સફર અને ગેટવે ચુકવણી નોંધાઈ શકતી નથી.',
    'docs_led_s4' => '4. ચાર્જ બનાવનારી પ્રક્રિયા ગોઠવો',
    'docs_led_s4_desc' => 'રોજની એક પ્રક્રિયા દરેક કરારનો ભાડા ચાર્જ લેણો થતાં જ ઊભો કરે છે. તે વિલંબ ફી અને સ્મરણપત્રની પ્રક્રિયાઓ પહેલાં ચાલવી જોઈએ, કારણ કે તે એ જ ચાર્જ વાંચે છે. તેના વગર બાકી રકમ થીજી જાય છે અને કોઈને યાદ કરાવાતું નથી.',
    'docs_led_accounts' => 'ખાતાંની યાદી',
    'docs_led_accounts_desc' => 'તમે ઇચ્છો તેટલાં ખાતાં બનાવી શકો છો. કેટલાંક તમારા માટે બની જાય છે અને તેમના પર સિસ્ટમની નિશાની હોય છે — આપોઆપ થતી નોંધો તેમના પર આધારિત છે, તેથી તે રદ કરી શકાતાં નથી, જોકે નામ બદલી શકાય છે.',
    'docs_led_a_asset' => 'સંપત્તિ',
    'docs_led_a_asset_d' => 'બેંક ખાતાં, રોકડ પેટીઓ, ફ્લોટ, અને ભાડૂતો પાસે જે લેણું છે તે',
    'docs_led_a_liab' => 'જવાબદારીઓ',
    'docs_led_a_liab_d' => 'ભાડૂતો વતી તમારી પાસે રહેલી ડિપોઝિટ, અને પુરવઠાદારોનું તમારા પર જે લેણું છે તે',
    'docs_led_a_eq' => 'મૂડી',
    'docs_led_a_eq_d' => 'શરૂઆતની બાકી અને એકઠો થયેલો નફો',
    'docs_led_a_inc' => 'આવક',
    'docs_led_a_inc_d' => 'ભાડું, વિલંબ ફી, વસૂલેલી સેવાઓ, જપ્ત થયેલી ડિપોઝિટ',
    'docs_led_a_exp' => 'ખર્ચ',
    'docs_led_a_exp_d' => 'જેના પર પણ તમે પૈસા વાપરો છો; જેટલાં પર અહેવાલ જોઈએ તેટલાં ઉમેરો',
    'docs_led_kind_note' => '"જાત" વાળું ખાનું શણગાર નથી — તે નક્કી કરે છે કે ખાતું ક્યાં દેખાશે. રોકડ બેંકમાં ભરતી વખતે મુકામ તરીકે ફક્ત બેંક ખાતું ચિહ્નિત ખાતાં દેખાય છે, અને ખર્ચ ચૂકવતી વખતે સ્રોત ફક્ત બેંક કે રોકડ ખાતાં હોઈ શકે. સામાન્ય તરીકે છોડેલું ખાતું ફક્ત હાથે કરેલી નોંધો માટે જ ઉપલબ્ધ રહે છે.',
    'docs_led_currency_note' => 'દરેક ખાતું એક જ ચલણ રાખે છે. USD નું બેંક ખાતું TZS વાળા કરતાં અલગ ખાતું છે, અને કોઈ નોંધ ચલણ ભેળવી શકતી નથી. એ જ કારણે પત્રકો પણ દરેક ચલણ માટે અલગ બને છે.',
    'docs_led_float_h' => 'ફ્લોટ અને રવાનગી',
    'docs_led_float_h_desc' => 'રોકડ બે જગ્યાએ રહે છે. વ્યક્તિગત ફ્લોટ ત્યારે આપોઆપ બને છે જ્યારે કોઈ પહેલી વાર રોકડ ચુકવણી નોંધે, અને તે તેના જ નામે હોય છે. સહિયારી રોકડ પેટી એ છે જે તમે જાતે ખાતાંની યાદીમાં બનાવો છો — જાત રોકડ રાખો — અને તે કોઈ એકની હોતી નથી. બંને એક જ રીતે બેંકમાં જાય છે; ફરક એટલો કે ફ્લોટ કહી શકે કે પૈસા કોની પાસે હતા, સહિયારી પેટી નહીં.',
    'docs_led_f1' => 'કોઈ વસૂલનાર રોકડ ચુકવણી નોંધે છે. તેનો ફ્લોટ વધે છે.',
    'docs_led_f2' => 'તે પૈસા બેંકમાં ભરે છે, પછી ખાતાવહી &rsaquo; ફ્લોટ ખોલીને "રોકડ બેંકમાં ભરો" પર ક્લિક કરે છે અને રકમ, મુકામ ખાતું તથા ભરણા ચિઠ્ઠી નંબર ભરે છે.',
    'docs_led_f3' => 'હજુ કશું ખસતું નથી. ફ્લોટમાં રોકડ હજુ દેખાય છે.',
    'docs_led_f4' => 'બીજી કોઈ વ્યક્તિ તેને મંજૂર કરે છે. ત્યારે જ ફ્લોટ ઘટે છે અને બેંક વધે છે.',
    'docs_led_f_note' => 'કઈ રીતો કોઈના હાથમાં રોકડ મૂકે છે તે ખાતાવહી &rsaquo; ખાતાં જોડાણમાં નક્કી થાય છે. મૂળભૂત રીતે ફક્ત રોકડ: ચેક બેંકમાં ભરાય છે, રખાતો નથી, અને ટ્રાન્સફર તથા ગેટવે ચુકવણી કોઈના હાથમાંથી પસાર જ થતી નથી.',
    'docs_led_approval' => 'શેને મંજૂરી જોઈએ',
    'docs_led_approval_desc' => 'નિયમ સાદો છે: જે બન્યું તે નોંધવું કદી અટકાવાતું નથી, પણ પૈસા બહાર જાય ત્યારે હંમેશાં બીજી વ્યક્તિ જોઈએ.',
    'docs_led_action' => 'ક્રિયા',
    'docs_led_needs' => 'મંજૂરી',
    'docs_led_ap1' => 'ચુકવણી કે ડિપોઝિટ નોંધવી',
    'docs_led_no' => 'ના',
    'docs_led_ap2' => 'હજુ ન ચૂકવાયેલો ખર્ચ નોંધવો',
    'docs_led_ap3' => 'વસૂલેલી રોકડ બેંકમાં ભરવી',
    'docs_led_yes' => 'હા',
    'docs_led_ap4' => 'પુરવઠાદારને ચૂકવવું',
    'docs_led_ap5' => 'ડિપોઝિટ પરત આપવી કે જપ્ત કરવી',
    'docs_led_ap6' => 'હાથે કરેલી નોંધ કે શરૂઆતની બાકી',
    'docs_led_self_note' => 'મૂળભૂત રીતે એક વ્યક્તિ પોતાની જ વિનંતી મંજૂર કરી શકે છે, અને એટલે જ એકલો મકાનમાલિક સિસ્ટમ ચલાવી શકે છે. ખાતાવહી &rsaquo; ખાતાં જોડાણમાં "પોતાની જ વિનંતીઓ મંજૂર કરવા દો" બંધ કરો, તો પૈસા બહાર જવા માટે હંમેશાં બીજી વ્યક્તિ જોઈશે — અહીંનું એકમાત્ર નિયંત્રણ જેને એકલો વપરાશકર્તા તોડી ન શકે. બંધ હોય અને એક જ મંજૂરી આપનાર હોય તો કશું કદી મંજૂર થશે નહીં.',
    'docs_led_statements' => 'પત્રકો',
    'docs_led_statements_desc' => 'ખાતાવહી &rsaquo; પત્રકોમાં ત્રણ દૃશ્ય છે, બધાં દરેક ચલણ માટે અલગ:',
    'docs_led_st_pl' => 'નફો &amp; નુકસાન',
    'docs_led_st_pl_d' => 'એક ગાળાની આવક અને ખર્ચ, જેને એક મિલકત સુધી ગાળી શકાય. આવક તે લેણી થઈ ત્યારે અને ખર્ચ તે થયો ત્યારે ગણાય છે, રોકડ ફરી ત્યારે નહીં.',
    'docs_led_st_bs' => 'સરવૈયું',
    'docs_led_st_bs_d' => 'કોઈ પણ તારીખે તમારી પાસે શું છે, તમારા પર શું લેણું છે અને શું બચે છે. અનામત નફો તે તારીખ સુધીની બધી આવક અને ખર્ચમાંથી ગણાય છે.',
    'docs_led_st_ag' => 'ઉંમર પ્રમાણે દેવાદારો',
    'docs_led_st_ag_d' => 'કોના પર શું બાકી છે, કેટલું મોડું થયું તે પ્રમાણે વહેંચીને: ચાલુ, 31–60, 61–90 અને 90 દિવસથી વધુ.',
    'docs_led_drill' => 'દરેક આંકડો કડી છે. તે ખાતાની ખાતાવહી સુધી ક્લિક કરીને જાઓ અને ચાલુ બાકી સાથે દરેક હલચલ જુઓ, અને ત્યાંથી તેની પાછળની નોંધ સુધી. કોઈ આંકડો ખોટો લાગે તો કારણ જાણવાનો આ સૌથી ઝડપી રસ્તો છે.',
    'docs_led_tb' => 'કાચું સરવૈયું તંદુરસ્તીની ચકાસણી છે: ઉધાર અને જમા સરખા હોવા જોઈએ. દરેક નોંધ સાચવતી વખતે ચકાસાય છે, તેથી કદી ફેર દેખાય તો કોઈએ એપ્લિકેશનની બહારથી ડેટાબેઝ બદલ્યો છે.',
    'docs_led_closing' => 'ગાળો બંધ કરવો',
    'docs_led_closing_desc' => 'જે મહિનાનો અહેવાલ બની ગયો તેને બંધ કરો: ખાતાવહી &rsaquo; ખાતાં જોડાણ &rsaquo; ચોપડા બંધ કરો, અને તારીખ ગોઠવો. પછી તે તારીખે કે તે પહેલાં કશું નોંધાઈ શકતું નથી — ન કોઈ વ્યક્તિથી, ન API કૉલથી, ન ગોઠવેલી પ્રક્રિયાથી. ફરી ખોલવા તારીખ ભૂંસી નાખો.',
    'docs_led_faq' => 'સામાન્ય પ્રશ્નો',
    'docs_led_q1' => 'બધાની બાકી શૂન્ય દેખાય છે.',
    'docs_led_q1_a' => 'ચાર્જ બનાવનારી પ્રક્રિયા ચાલી જ નથી. બાકી એટલે ન ભરાયેલા ચાર્જનો સરવાળો, તેથી જ્યાં સુધી ચાર્જ ન બને ત્યાં સુધી કશું બાકી જ નથી. એક વાર હાથે ચલાવો, પછી રોજ માટે ગોઠવી દો.',
    'docs_led_q2' => 'કોઈ ચુકવણી ખાતાવહી સુધી પહોંચી નથી.',
    'docs_led_q2_a' => 'મોટે ભાગે ડિફોલ્ટ બેંક ખાતું જોડાયેલું નથી, અથવા તે ચુકવણીના ચલણમાં કોઈ ખાતું જ નથી. ચુકવણી પોતે બરાબર નોંધાયેલી છે — ફક્ત ખાતાવહીની નોંધ ખૂટે છે, અને ખાતું બનતાં જ તે નોંધી શકાય છે.',
    'docs_led_q3' => 'ફ્લોટમાં એ રોકડ હજુ દેખાય છે જે દિવસો પહેલાં બેંકમાં ભરાઈ હતી.',
    'docs_led_q3_a' => 'રવાનગી મંજૂરીની રાહ જુએ છે. ફ્લોટનું પત્રક ખોલો — તેમાં જાહેર કરેલી પણ હજુ મંજૂર ન થયેલી રકમ દેખાય છે, અને મંજૂરી પછી બાકી શું થશે તે પણ.',
    'docs_led_q4' => 'ભૂલથી નોંધાયેલી એન્ટ્રી સંપાદિત કરી શકાય?',
    'docs_led_q4_a' => 'ના, અને એ ઇરાદાપૂર્વક છે. એન્ટ્રી ખોલો અને ઉલટાવો પર ક્લિક કરો. તેથી તેને રદ કરતી અરીસા-નોંધ બને છે, જેને પોતાને મંજૂરી જોઈએ. બંને ચોપડે રહે છે.',
    'docs_led_q5' => 'ખાતાવહી ચાલુ થતાં જ બાકી બદલાઈ ગઈ.',
    'docs_led_q5_a' => 'એ અપેક્ષિત છે. પહેલાં બાકીનો અંદાજ વીતેલા મહિના ગુણ્યા ભાડું, બાદ ચૂકવાયેલું બધું — એ રીતે થતો. હવે તે ન ભરાયેલા ચાર્જનો ચોક્કસ સરવાળો છે, તેથી આંશિક ચુકવણી અને વચગાળાના ફેરફારો બરાબર દેખાય છે.',
    // Unit profitability (part 37)
    'rep_unit_pl' => 'એકમવાર નફાકારકતા',
    'rep_up_shared' => 'સહિયારો ખર્ચ',
    'rep_up_equal' => 'સરખે ભાગે',
    'rep_up_by_rent' => 'ભાડાના પ્રમાણમાં',
    'rep_up_no_shared' => 'આ ગાળામાં કોઈ સહિયારો ખર્ચ નથી',
    'rep_up_income' => 'આવક',
    'rep_up_direct' => 'સીધો ખર્ચ',
    'rep_up_apportioned' => 'સહિયારા ખર્ચનો ભાગ',
    'rep_up_total_cost' => 'કુલ ખર્ચ',
    'rep_up_net' => 'ચોખ્ખું',
    'rep_up_margin' => 'માર્જિન',
    'rep_up_unallocated' => 'કોઈ મિલકત સાથે જોડાયેલ નથી',
    'rep_up_unallocated_help' => 'આ અહીં દર્શાવાય છે, એકમો પર નાખવામાં આવતો નથી — તેથી ઉપરના કુલ એ જ ગાળાના નફા-નુકસાન કરતાં ઓછા છે.',
    'rep_up_note' => 'મિલકત પર નોંધાયેલો પણ કોઈ એકમ પર નહીં એવો ખર્ચ — છત, ચોકીદાર, પાણીની મુખ્ય લાઇન — દરેક એકમના ભાડાના પ્રમાણમાં વહેંચાય છે. ખાલી એકમો પણ સામેલ છે અને પોતાનો ભાગ ઉઠાવે છે, તેથી તેમનું નુકસાન એ જ ખાલી રહેવાની કિંમત છે. ભાગ એકમના હાલના ભાડા પરથી ગણાય છે, તેથી ભાડું બદલતાં ગયા ગાળા પણ બદલાય છે.',
    // Receipt account picker (part 38)
    'rcp_account' => 'કયામાં મળ્યું',
    'rcp_auto' => 'આપોઆપ નક્કી કરો',
    'rcp_help_cash' => 'ફક્ત રોકડ પેટીઓ અને ફ્લોટ — આ પૈસા હજુ બેંક સુધી પહોંચ્યા નથી.',
    'rcp_help_bank' => 'ફક્ત બેંક ખાતાં.',
    'rcp_help_none' => 'આ ચલણમાં કોઈ મળતું ખાતું નથી. તે આપોઆપ નક્કી થશે.',
    // Cash and approval policy (part 38)
    'led_cash_policy' => 'રોકડ અને મંજૂરીઓ',
    'led_cash_methods' => 'જે રીતો કોઈના હાથમાં રોકડ મૂકે છે',
    'led_cash_methods_help' => 'આ રોકડ પેટી કે ફ્લોટમાં જાય છે અને બેંકના પૈસા ત્યારે જ ગણાય જ્યારે બેંકમાં ભરાય. બાકી બધું સીધું બેંક ખાતામાં નોંધાય છે.',
    'led_self_approve' => 'પોતાની જ વિનંતીઓ મંજૂર કરવા દો',
    'led_self_approve_help' => 'ચાલુ હોય તો એક જ વ્યક્તિ રોકડ નોંધી શકે અને તેને બેંકમાં ભરવાની મંજૂરી પણ આપી શકે — એકલા સિસ્ટમ ચલાવતા હો તો જરૂરી છે. બંધ હોય તો પૈસા બહાર જવા માટે હંમેશાં બીજી વ્યક્તિ જોઈએ, અને એ જ અહીંનું એકમાત્ર નિયંત્રણ છે જેને એકલો વપરાશકર્તા તોડી ન શકે.',
    'led_err_no_cash_method' => 'ઓછામાં ઓછી એક રીત પસંદ કરો, નહીં તો કોઈ કદી રોકડ રાખી શકશે નહીં',
    // Part 38 documentation
    'docs_led_receipt' => 'મળેલી રકમ ક્યાં જાય તે પસંદ કરવું',
    'docs_led_receipt_desc' => 'ચુકવણી કે ડિપોઝિટ નોંધતી વખતે "કયામાં મળ્યું" નું ખાનું મળે છે. તેમાં શું દેખાશે તે રીત પર આધારિત છે: રોકડ ફક્ત રોકડ પેટી કે ફ્લોટમાં જ જઈ શકે, અને ટ્રાન્સફર કે ચેક ફક્ત બેંક ખાતામાં. આ ચીકણાઈ નથી — રોકડને સીધી બેંક ખાતામાં નાખવી એટલે એવો દાવો કરવો કે પૈસા બેંક પહોંચી ગયા, જ્યારે તેમને ત્યાં કોઈ લઈ ગયું જ નથી.',
    'docs_led_receipt_auto' => '"આપોઆપ નક્કી કરો" પર છોડો તો તે હંમેશની જેમ ચાલે છે: રોકડ નોંધનારના ફ્લોટમાં જાય છે, અને બાકી બધું ડિફોલ્ટ બેંક તરીકે જોડાયેલા ખાતામાં. જ્યાં જ્યાં ખરેખર પૈસા રખાય છે — રિસેપ્શન, સાઇટ ઓફિસ — ત્યાં એક એક રોકડ પેટી બનાવો, તો બાકી દરેક પેટીમાં રહેલા પૈસા સાથે મળતી આવશે.',

    // Part 39 — automatic billing start
    'lease_bill_from' => 'આ તારીખથી આપમેળે બિલિંગ',
    'lease_bill_from_help' => 'શરૂઆતની તારીખથી ભાડું બિલ કરવા માટે ખાલી રાખો. જ્યારે આ લીઝ આ સિસ્ટમનો ઉપયોગ શરૂ કર્યા પહેલાં શરૂ થઈ હોય ત્યારે તે ભરો: આ તારીખ પહેલાંનું ભાડું બિલ નહીં થાય, તેથી જે પણ બાકી છે તે શરૂઆતના બાકી તરીકે દાખલ કરો.',
    'lease_bill_from_edit_help' => 'આ તારીખ પહેલાંનું ભાડું આપમેળે બિલ થતું નથી. તેને વહેલી તારીખે ખસેડવાથી સિસ્ટમ આગલી વખતે અગાઉના સમયગાળાનું બિલ બનાવશે, તેથી એવું ત્યારે જ કરો જ્યારે તે ક્યારેય બિલ ન થયા હોય કે બાકી તરીકે દાખલ ન થયા હોય.',
    'lease_bill_from_view_help' => 'અગાઉનું ભાડું આ સિસ્ટમ પહેલાં, શરૂઆતના બેલેન્સ તરીકે બિલ થયું હતું.',
    'lease_bill_from_invalid' => 'આપમેળે બિલિંગની તારીખ માન્ય નથી',
    'lease_bill_from_after_end' => 'આપમેળે બિલિંગની તારીખ સમાપ્તિ તારીખ પછી ન હોઈ શકે',

    // Part 40 — opening data import
    'imp_t_rent_roll' => 'ભાડા પત્રક (Rent roll)',
    'imp_t_rent_roll_what' => 'દરેક પંક્તિ પરની પ્રોપર્ટી, યુનિટ અને ભાડૂત હજી ન હોય તો બનાવે છે, પછી એક સક્રિય લીઝ બનાવે છે, અને તમે આપો તો રાખેલ ડિપોઝિટ પણ નોંધે છે.',
    'imp_t_rent_roll_where' => 'પ્રોપર્ટીઓ, યુનિટ્સ (ભાડે અપાયેલ તરીકે ચિહ્નિત), ભાડૂતો, લીઝ અને ડિપોઝિટ્સ. આ લીઝનું આપમેળે ભાડા બિલિંગ ગો-લાઇવ તારીખથી શરૂ થાય છે.',
    'imp_t_rent_roll_books' => 'લીઝથી હિસાબમાં કંઈ નોંધાતું નથી. રાખેલ ડિપોઝિટ "ભાડૂતોની રાખેલ ડિપોઝિટ" માં ઉમેરાય છે, તેની સામે "શરૂઆતની બાકીની મૂડી" માં સરભર થાય છે, અને ગો-લાઇવના આગલા દિવસની તારીખે નોંધાય છે.',
    'imp_t_rent_roll_not' => 'ભાડૂતો પાસે કેટલું બાકી છે તે આ નોંધતું નથી — તે માટે શરૂઆતના બાકી વાપરો — અને ભાડૂતોને કોઈ સંદેશ મોકલતું નથી.',
    'imp_c_property_name' => 'નામથી હાલની પ્રોપર્ટી સાથે મેળવાય છે, અથવા નવી બનાવાય છે',
