    'imp_t_arrears_books' => 'દરેક પંક્તિ "ભાડૂતો પાસેથી લેણું" માં ઉમેરાય છે, તેની સામે "શરૂઆતની બાકીની મૂડી" માં સરભર થાય છે, અને ગો-લાઇવના આગલા દિવસની તારીખે નોંધાય છે.',
