    'imp_t_deposits' => 'રાખેલ ડિપોઝિટ્સ',
    'imp_t_deposits_what' => 'પહેલેથી અસ્તિત્વમાં હોય તેવી દરેક લીઝ માટે આજે તમારી પાસે રાખેલ ડિપોઝિટ નોંધે છે.',
    'imp_t_deposits_where' => 'ડિપોઝિટ યાદી, લીઝ અને ભાડૂતનાં પૃષ્ઠો, અને ખાલી કરતી વખતે પરત.',
    'imp_t_deposits_books' => '"ભાડૂતોની રાખેલ ડિપોઝિટ" માં ઉમેરાય છે, તેની સામે "શરૂઆતની બાકીની મૂડી" માં સરભર થાય છે, અને ગો-લાઇવના આગલા દિવસની તારીખે નોંધાય છે. રોકડ પોતે તમારી શરૂઆતની બેંક બાકીમાં હોવી જોઈએ.',
    'imp_t_deposits_not' => 'આ કોઈ પૈસા બેંક કે રોકડ ખાતામાં મૂકતું નથી, અને કોઈ રસીદ મોકલતું નથી.',
