    'imp_t_advances' => 'ભાડૂતના એડવાન્સ',
    'imp_t_advances_what' => 'ભાડૂતે અગાઉથી ચૂકવેલું ભાડું તેની લીઝ પર જમા (ક્રેડિટ) તરીકે નોંધે છે.',
    'imp_t_advances_where' => 'ભાડૂતના આગળના ચાર્જ બને તેમ આ જમા રકમ તેમને આપમેળે ચૂકવે છે. તે ગો-લાઇવના આગલા દિવસની તારીખની ચુકવણી તરીકે દેખાય છે, સંદર્ભ OPENING-ADVANCE.',
    'imp_t_advances_books' => '"ભાડૂતો પાસેથી લેણું" ઘટાડે છે, તેની સામે "શરૂઆતની બાકીની મૂડી" માં સરભર થાય છે, અને ગો-લાઇવના આગલા દિવસની તારીખે નોંધાય છે.',
    'imp_t_advances_not' => 'આ નવા મળેલા પૈસા નથી અને કોઈ રસીદ બનાવતું નથી. રોકડ પોતે તમારી શરૂઆતની બેંક બાકીમાં હોવી જોઈએ.',
