    'imp_t_tb_where' => 'કાચું સરવૈયું, સરવૈયું (બેલેન્સ શીટ) અને દરેક ખાતાનું પત્રક.',
    'imp_t_tb_books' => 'તમે યાદીમાં આપેલાં ખાતાંને ઉધાર અને જમા કરે છે. તફાવત "શરૂઆતની બાકીની મૂડી" માં જાય છે. આ નોંધ ગણાય તે પહેલાં બીજા મંજૂર કરનારની રાહ જુએ છે.',
    'imp_t_tb_not' => '"ભાડૂતો પાસેથી લેણું", "રાખેલ ડિપોઝિટ" અને "ચૂકવવાપાત્ર" અહીં સ્વીકારાતાં નથી: તેમની બાકી શરૂઆતના બાકી, ડિપોઝિટ અને એડવાન્સના ઈમ્પોર્ટમાંથી આવે છે, જેથી તે ક્યારેય બે વાર ન ગણાય.',
