    'imp_banner' => 'સિસ્ટમ વાપરવાનું શરૂ કરો ત્યારે જે પહેલેથી અસ્તિત્વમાં છે તે લાવવા આ પૃષ્ઠ વાપરો: તમારી પ્રોપર્ટીઓ, યુનિટ્સ, ભાડૂતો અને લીઝ, આજે ભાડૂતો પાસે તમારું કેટલું બાકી છે, તમારી પાસે રાખેલ ડિપોઝિટ્સ, અને તમારાં ખાતાંની બાકી. ઈમ્પોર્ટ સાચા રેકોર્ડ લખે છે. બાકી રકમો, ડિપોઝિટ્સ અને બાકી સીધી બાકીની યાદી, ભાડૂત પત્રકો અને તમારાં ખાતાંમાં જાય છે. પગલાં ક્રમમાં પૂરાં કરો, દરેક પ્રિવ્યૂ ધ્યાનથી તપાસો, અને તમારા આંકડા જૂના રેકોર્ડ સાથે મળે ત્યારે "સેટઅપ પૂર્ણ કરો" પર ક્લિક કરો.',
