    'imp_reopen_help' => 'તેમને સુધારવા, મંજૂરી અધિકાર ધરાવતા એડમિન ખાતાવહી → ખાતા જોડાણ માં "આ તારીખ સુધી બંધ" તારીખ ખાલી કરીને અથવા ખસેડીને ચોપડા ફરી ખોલી શકે છે. ફરી ખોલવાથી તમારી શરૂઆતની બાકી બદલી શકાય છે, અને અગાઉના સમયગાળાના અહેવાલો બદલાઈ શકે છે. કામ પૂરું થાય ત્યારે ફરી બંધ કરો.',
